        },
        {
            "col1": "test",
            "col2": "1"
        },
        {
            "col1": "test",
            "col2": "1"
        },
        {
            "col1": "test",
            "col2": "1"
        },
        {
            "col1": "test",
            "col2": "1"
        },
        {
            "col1": "test",
            "col2": "1"
        },
        {
            "col1": "test",
            "col2": "2"
        },
        {
            "col1": "test",
            "col2": "2"
        },
        {
            "col1": "test",
            "col2": "2"
        },
        {
            "col1": "test",
            "col2": "2"
        },
        {
            "col1": "test",
            "col2": "2"
        }
    ];
    var jsonData2 = [{
            "code": "code1",
            value: "1"
        },
        {
            "code": "code2",
            value: "2"
        }
    ];
    dlt_select.setJSON(jsonData2);
    dataList1.setJSON(jsonData1);
};
scwin.confirm_check = function(id, property, value) {
    var arr = jQuery("*[col_id='" + id + "']");
    var a = 0;
    for (var i = 0; i < arr.length; i++) {
        var iD = arr[i].id;
        (WebSquare.wUnit.getDomById($p.id + iD).getAttribute(property) == value) ? a++ : '';
    }
    return arr.length == a;
}
scwin.checkVal1 = function() {
    return scwin.confirm_check('col1', 'colmerge', 'true');
}
scwin.checkVal2 = function() {
    return scwin.confirm_check('col2', 'colmerge', 'true');
}
scwin.checkVal3 = function() {
    return scwin.confirm_check('col2', 'viewtype', 'icon');
}
scwin.unitTest = function(){
    //init
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_scrollY_div').scrollTop = 50");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_scrollY_div').scrollTop = 80");

    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('gridBodyDefault gridBodyDefault_data '+$p.id+'wq_uuid_5_columnstyle_1_ gridBodyDefault_select').length == 2", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 05-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
